import {
  drmBatchGames,
  refreshReleaseDrmBatch,
  requestReleaseDrm,
  subscribeReleaseDrm
} from 'frontend/helpers/releaseDrmRequests'
import type { ReleaseProduct } from 'common/types/releases'
import type { ReleaseDrmReport, ReleaseDrmStatus } from 'common/releaseDrm'

const mockDrm = jest.fn()
const game = (id: string, category = 'games'): ReleaseProduct => ({
  id,
  title: id,
  category,
  url: `https://www.releases.com/p/${id}`,
  platforms: ['PC'],
  dateLabel: 'TBA',
  region: 'us',
  releases: [],
  images: [],
  videos: [],
  tags: []
})
const report = (
  id: string,
  status: ReleaseDrmStatus = 'cracked'
): ReleaseDrmReport => ({
  id,
  title: id,
  status,
  platform: 'PC',
  checkedAt: new Date().toISOString(),
  sources: [
    { name: 'IsItCracked', status, url: `https://isitcracked.com/game/${id}` }
  ]
})
beforeEach(() => {
  Object.defineProperty(globalThis, 'window', {
    configurable: true,
    value: { api: { releasesDrm: mockDrm } }
  })
  mockDrm.mockImplementation(async ({ id }) => report(id))
})
afterEach(() => jest.restoreAllMocks())

it('deduplicates calendar occurrences and tracked copies and excludes non-game categories', () => {
  expect(
    drmBatchGames([
      game('game-a'),
      game('game-a'),
      game('game-b'),
      game('movie', 'movies')
    ])
  ).toEqual([
    { id: 'game-a', title: 'game-a' },
    { id: 'game-b', title: 'game-b' }
  ])
})
it('stops automatic reads after confirmation but a general manual check forces every game', async () => {
  const games = [game('final-one'), game('final-two')]
  const listener = jest.fn()
  const unsubscribe = subscribeReleaseDrm(games[0], listener)
  await requestReleaseDrm(games[0])
  const realNow = Date.now()
  jest.spyOn(Date, 'now').mockReturnValue(realNow + 86400000)
  await requestReleaseDrm(games[0])
  expect(mockDrm).toHaveBeenCalledTimes(1)
  const progress = jest.fn()
  expect(
    await refreshReleaseDrmBatch(
      [...games, games[0]],
      progress,
      new AbortController().signal
    )
  ).toEqual({ total: 2, completed: 2, failed: 0, unconfirmed: 0 })
  expect(
    mockDrm.mock.calls.slice(1).every(([query]) => query.refresh === true)
  ).toBe(true)
  expect(listener).toHaveBeenCalledTimes(2)
  unsubscribe()
})
it.each(['uncracked', 'unknown', 'bypassed', 'conflicting'] as const)(
  'continues periodic checking for %s',
  async (status) => {
    const product = game('pending-' + status)
    mockDrm.mockImplementation(async () => report(product.id, status))
    await requestReleaseDrm(product)
    const realNow = Date.now()
    jest.spyOn(Date, 'now').mockReturnValue(realNow + 16 * 60000)
    await requestReleaseDrm(product)
    expect(mockDrm).toHaveBeenCalledTimes(2)
  }
)
it('keeps at most two requests active and stopping does not dispatch remaining games', async () => {
  const pending: ((report: ReleaseDrmReport) => void)[] = []
  mockDrm.mockImplementation(
    () => new Promise<ReleaseDrmReport>((resolve) => pending.push(resolve))
  )
  const controller = new AbortController()
  const run = refreshReleaseDrmBatch(
    [game('cancel-a'), game('cancel-b'), game('cancel-c')],
    jest.fn(),
    controller.signal
  )
  expect(mockDrm).toHaveBeenCalledTimes(2)
  controller.abort()
  pending[0](report('cancel-a'))
  pending[1](report('cancel-b'))
  expect(await run).toMatchObject({ total: 3, completed: 2 })
  expect(mockDrm).toHaveBeenCalledTimes(2)
})
it('reports failed and unconfirmed requests and continues the batch', async () => {
  mockDrm.mockImplementation(async ({ id }) => {
    if (id === 'failure') throw new Error('Offline')
    return report(id, id === 'no-confirmation' ? 'unknown' : 'cracked')
  })
  expect(
    await refreshReleaseDrmBatch(
      [game('failure'), game('no-confirmation'), game('success')],
      jest.fn(),
      new AbortController().signal
    )
  ).toMatchObject({ completed: 3, failed: 1, unconfirmed: 1 })
})

import { mkdtemp, mkdir, readFile, writeFile, rm } from 'fs/promises'
import { resolve, join, sep } from 'path'

let mockDirectory: string
const mockLoad = jest.fn()
const mockRead = jest.fn()
const mockFetch = jest.fn()
jest.mock('../drmSheets', () => ({
  getCrackWatchSheetSources: async () => ({
    sources: [],
    warning: '',
    stale: false
  })
}))
jest.mock('../drmSites', () => ({ getAdditionalDrmSources: async () => [] }))
jest.mock('electron', () => ({
  app: { getPath: () => mockDirectory },
  net: { fetch: (...args: unknown[]) => mockFetch(...args) },
  session: {
    fromPartition: () => ({
      setPermissionRequestHandler: jest.fn(),
      webRequest: { onBeforeRequest: jest.fn() }
    })
  },
  BrowserWindow: jest.fn().mockImplementation(() => ({
    loadURL: (...args: unknown[]) => mockLoad(...args),
    isDestroyed: () => false,
    destroy: jest.fn(),
    webContents: {
      setAudioMuted: jest.fn(),
      setWindowOpenHandler: jest.fn(),
      on: jest.fn(),
      executeJavaScript: () => mockRead()
    }
  }))
}))

it.each(['cracked', 'drm-free'] as const)(
  'persists %s across failures, cache eviction and restarts; manual refresh and uncracked games still reach providers',
  async (status) => {
    const root = resolve('build/release-drm-tests')
    await mkdir(root, { recursive: true })
    mockDirectory = await mkdtemp(join(root, 'metadata-'))
    try {
      jest.resetModules()
      const { getReleaseDrm } = await import('../drm')
      jest.requireMock('electron').BrowserWindow.mockImplementation(() => ({
        loadURL: (...args: unknown[]) => mockLoad(...args),
        isDestroyed: () => false,
        destroy: jest.fn(),
        webContents: {
          setAudioMuted: jest.fn(),
          setWindowOpenHandler: jest.fn(),
          on: jest.fn(),
          executeJavaScript: () => mockRead()
        }
      }))
      mockLoad.mockResolvedValue(undefined)
      mockRead.mockResolvedValue({
        title: 'Persona 3 Reload',
        status: status === 'cracked' ? 'Cracked' : 'DRM Free',
        protection: 'Denuvo',
        group: 'voices38',
        crackDate: 'Sep 5, 2026'
      })
      mockFetch.mockResolvedValue({
        ok: true,
        text: async () => JSON.stringify({ data: { children: [] } })
      })
      const original = await getReleaseDrm({
        id: 'persona-3-reload',
        title: 'Persona 3 Reload',
        refresh: true
      })
      expect(original.status).toBe(status)
      mockLoad.mockRejectedValueOnce(new Error('Network unavailable'))
      mockFetch.mockResolvedValue({ ok: false, status: 403 })
      const offline = await getReleaseDrm({
        id: 'persona-3-reload',
        title: 'Persona 3 Reload',
        refresh: true
      })
      expect(offline).toMatchObject({
        status,
        stale: true,
        checkedAt: original.checkedAt
      })
      expect(
        offline.sources.find((source) => source.name === 'IsItCracked')
      ).toEqual(original.sources[0])
      mockRead.mockResolvedValue({ title: 'Game not found' })
      const changed = await getReleaseDrm({
        id: 'persona-3-reload',
        title: 'Persona 3 Reload',
        refresh: true
      })
      expect(changed).toMatchObject({
        status,
        stale: true,
        checkedAt: original.checkedAt
      })
      const stored = JSON.parse(
        await readFile(
          join(mockDirectory, 'releases', 'drm-cache.json'),
          'utf8'
        )
      )
      expect(stored[0].report.status).toBe(status)
      expect(stored[0].report.sources).toContainEqual(
        expect.objectContaining({ name: 'IsItCracked', group: 'voices38' })
      )
      expect(
        mockFetch.mock.calls.filter((call) =>
          String(call[0]).includes('/search.json')
        )
      ).toHaveLength(2)
      const calls = mockLoad.mock.calls.length
      const netCalls = mockFetch.mock.calls.length
      const realNow = Date.now()
      jest.spyOn(Date, 'now').mockReturnValue(realNow + 2 * 86400000)
      expect(
        (await getReleaseDrm({ id: original.id, title: original.title })).status
      ).toBe(status)
      expect(mockLoad).toHaveBeenCalledTimes(calls)
      // Simulate eviction from the rolling cache and a new application process.
      await writeFile(join(mockDirectory, 'releases', 'drm-cache.json'), '[]')
      jest.resetModules()
      const restarted = await import('../drm')
      const restored = await restarted.getReleaseDrm({
        id: original.id,
        title: original.title
      })
      expect(restored).toMatchObject({
        status,
        checkedAt: original.checkedAt
      })
      expect(mockLoad).toHaveBeenCalledTimes(calls)
      expect(mockFetch).toHaveBeenCalledTimes(netCalls)
      // An explicit manual check still reaches the providers and can change the verdict.
      mockRead.mockResolvedValue({ title: original.title, status: 'Uncracked' })
      mockFetch.mockResolvedValue({
        ok: true,
        text: async () => JSON.stringify({ data: { children: [] } })
      })
      expect(
        (
          await restarted.getReleaseDrm({
            id: original.id,
            title: original.title,
            refresh: true
          })
        ).status
      ).toBe('uncracked')
      expect(mockLoad).toHaveBeenCalledTimes(calls + 1)
      await expect(
        readFile(
          join(
            mockDirectory,
            'releases',
            'drm-confirmed',
            stored[0].key + '.json'
          )
        )
      ).rejects.toMatchObject({ code: 'ENOENT' })
      jest.spyOn(Date, 'now').mockReturnValue(realNow + 3 * 86400000)
      await restarted.getReleaseDrm({ id: original.id, title: original.title })
      expect(mockLoad).toHaveBeenCalledTimes(calls + 2)
    } finally {
      jest.restoreAllMocks()
      if (resolve(mockDirectory).startsWith(root + sep))
        await rm(mockDirectory, { recursive: true, force: true })
    }
  }
)

import {
  parseDrmSiteGame,
  findDrmSiteGame,
  drmPageUnavailable
} from '../drmSitesParser'
import {
  safeDrmSourceUrl,
  combinedDrmStatus,
  isConfirmedDrmReport
} from 'common/releaseDrm'
import { getAdditionalDrmSources } from '../drmSites'

const mockFetch = jest.fn()
jest.mock('electron', () => ({
  net: { fetch: (...args: unknown[]) => mockFetch(...args) }
}))
const anker = 'https://ankergames.net/game/minecraft-dungeons-ii'
const skidrow = 'https://www.skidrowreloaded.com/minecraft-dungeons-ii-rune/'
const title = 'Minecraft Dungeons 2'
const document = (heading: string, content = '') =>
  `<main><h1>${heading}</h1>${content}</main>`

it('accepts only public metadata/search pages of the three additional sites', () => {
  for (const url of [
    anker,
    skidrow,
    'https://www.skidrowreloaded.com/?s=Persona%203',
    'https://ankergames.net/search/Persona%203',
    'https://hizsearch.pages.dev/'
  ])
    expect(safeDrmSourceUrl(url)).toBe(url)
  for (const url of [
    'https://ankergames.net.evil.example/game/test',
    'https://www.skidrowreloaded.com/go/malware',
    'https://www.skidrowreloaded.com/download/',
    'https://www.skidrowreloaded.com/wp-content/archive.zip',
    'https://hizsearch.pages.dev/api/search',
    'http://ankergames.net/game/test',
    'https://ankergames.net/game/test?download=1'
  ])
    expect(safeDrmSourceUrl(url)).toBeUndefined()
})
it('does not turn a scene tag, download, comment or Denuvo removal into a confirmed verdict', () => {
  const source = parseDrmSiteGame(
    document(
      'Minecraft Dungeons II',
      '<a href="/scene/rune">RUNE</a><div class="comments"><pre>DRM status: Cracked</pre></div><div class="installation"><pre>Crack: RUNE</pre></div><dl>Protection: Steam\nDenuvo removed</dl>'
    ),
    title,
    anker,
    'AnkerGames'
  )!
  expect(source).toMatchObject({ availability: 'listed', protection: 'Steam' })
  expect(source.status).toBeUndefined()
  expect(combinedDrmStatus([source])).toBe('unknown')
  expect(
    parseDrmSiteGame(
      document(
        'Minecraft Dungeons II',
        '<pre>DRM status: DRM removed (Denuvo)</pre>'
      ),
      title,
      anker,
      'AnkerGames'
    )?.status
  ).toBeUndefined()
})
it('requires a matching complete title and explicit metadata for confirmation', () => {
  const source = parseDrmSiteGame(
    document(
      'Minecraft Dungeons II-RUNE',
      '<pre>Protection: Steam\nCracked by: RUNE</pre>'
    ),
    title,
    skidrow,
    'SkidrowReloaded'
  )!
  expect(source).toMatchObject({
    status: 'cracked',
    group: 'RUNE',
    protection: 'Steam'
  })
  for (const heading of [
    'Minecraft Dungeons II Deluxe Edition-RUNE',
    'Minecraft Dungeons II Update v1.2-RUNE',
    'Minecraft Dungeons II v1.2 Deluxe Edition-RUNE',
    'Minecraft Dungeons'
  ])
    expect(
      parseDrmSiteGame(
        document(heading, '<pre>DRM status: Cracked</pre>'),
        title,
        skidrow,
        'SkidrowReloaded'
      )
    ).toBeUndefined()
  expect(
    parseDrmSiteGame(
      document('Minecraft Dungeons II') +
        '<article><h1>Another game</h1><pre>Crack: RUNE</pre></article>',
      title,
      anker,
      'AnkerGames'
    )?.status
  ).toBeUndefined()
})
it('finds matching result links, rejecting other editions and untrusted destinations', () => {
  expect(
    findDrmSiteGame(
      '<a href="/game/minecraft-dungeons-ii">Minecraft Dungeons II</a>',
      title,
      'AnkerGames'
    )
  ).toBe(anker)
  expect(
    findDrmSiteGame(
      '<a href="/minecraft-dungeons-ii-rune/">Minecraft Dungeons II-RUNE</a>',
      title,
      'SkidrowReloaded'
    )
  ).toBe(skidrow)
  expect(
    findDrmSiteGame(
      '<a href="https://evil.example/game/minecraft-dungeons-ii">Minecraft Dungeons II</a>',
      title,
      'AnkerGames'
    )
  ).toBeUndefined()
})
it.each([
  ['DRM-free', 'drm-free', true],
  ['Hypervisor', 'bypassed', false],
  ['Uncracked', 'uncracked', false]
])('only freezes a final status (%s)', (label, status, frozen) => {
  const source = parseDrmSiteGame(
    document('Minecraft Dungeons II', `<pre>DRM status: ${label}</pre>`),
    title,
    anker,
    'AnkerGames'
  )!
  expect(source.status).toBe(status)
  expect(
    isConfirmedDrmReport({
      id: 'game',
      title,
      platform: 'PC',
      status: source.status!,
      sources: [source],
      checkedAt: new Date().toISOString()
    })
  ).toBe(frozen)
})
it('detects maintenance and verification rather than claiming no matching game', () => {
  expect(
    drmPageUnavailable('<title>Skidrow is under maintenance</title>')
  ).toMatch(/manutenção/)
  expect(drmPageUnavailable('<title>Just a moment...</title>')).toMatch(
    /verificação/
  )
})
it('backs off across games even during a manual batch and retains all three source links', async () => {
  mockFetch.mockImplementation(
    async (url: string) =>
      new Response(
        url.includes('skidrow')
          ? '<title>Site is under maintenance</title>'
          : '',
        { status: url.includes('skidrow') ? 200 : 403 }
      )
  )
  const first = await getAdditionalDrmSources(title, true)
  expect(first).toHaveLength(3)
  expect(first[0].notice).toMatch(/manutenção/)
  expect(first[1].notice).toMatch(/403/)
  expect(first[2]).toMatchObject({
    name: 'HizSearch',
    notice: expect.stringMatching(/verificação manual/)
  })
  const calls = mockFetch.mock.calls.length
  await getAdditionalDrmSources('Persona 3 Reload', true)
  expect(mockFetch).toHaveBeenCalledTimes(calls)
  expect(first.every((source) => !source.status)).toBe(true)
})

import { BrowserWindow, session, net, app } from 'electron'
import { mkdir, readFile, writeFile, rename, unlink } from 'fs/promises'
import { join } from 'path'
import { createHash } from 'crypto'
import type { ReleaseDrmReport } from 'common/releaseDrm'
import {
  combinedDrmStatus,
  drmGameSlug,
  drmTitleAliases,
  normalizeDrmTitle,
  safeDrmSourceUrl,
  releaseDrmLabels,
  releaseDrmSourceLabels,
  isConfirmedDrmReport
} from 'common/releaseDrm'
import { parseIsItCracked, parseCrackWatch } from './drmParser'
import { getCrackWatchSheetSources } from './drmSheets'
import {
  CRACKWATCH_INDEX,
  drmSheetUrl,
  parseCrackWatchIndex
} from './drmCommunityParser'
import { DrmLookupQueue } from './drmQueue'
import { getAdditionalDrmSources } from './drmSites'

const reports = new Map<string, ReleaseDrmReport>()
const queue = new DrmLookupQueue<ReleaseDrmReport>()
let loading: Promise<void> | null = null
let sourceReady = false
let redditUnavailableUntil = 0
const lookupVersion = 3
let indexRead: Promise<unknown> | undefined
let indexCheckedAt = 0
let indexValue: unknown
let writer: Promise<unknown> = Promise.resolve()
const directory = () => join(app.getPath('userData'), 'releases')
const file = () => join(directory(), 'drm-cache.json')
const confirmedDirectory = () => join(directory(), 'drm-confirmed')
const reportKey = (report: Pick<ReleaseDrmReport, 'id' | 'title'>) =>
  createHash('sha256')
    .update(report.id + ':' + report.title)
    .digest('hex')
function validReport(key: string, report: ReleaseDrmReport) {
  return (
    /^[a-f0-9]{64}$/.test(key) &&
    report?.platform === 'PC' &&
    typeof report.title === 'string' &&
    report.title.length <= 300 &&
    typeof report.id === 'string' &&
    /^[a-z0-9._~-]{1,200}$/i.test(report.id) &&
    key === reportKey(report) &&
    Number.isFinite(Date.parse(report.checkedAt)) &&
    (report.warning === undefined || typeof report.warning === 'string') &&
    (report.stale === undefined || typeof report.stale === 'boolean') &&
    Array.isArray(report.sources) &&
    report.sources.length <= 24 &&
    report.sources.every(
      (source) =>
        source &&
        Object.hasOwn(releaseDrmSourceLabels, source.name) &&
        (!source.status || Object.hasOwn(releaseDrmLabels, source.status)) &&
        (!source.availability || source.availability === 'listed') &&
        typeof source.url === 'string' &&
        [
          'title',
          'protection',
          'crackDate',
          'group',
          'reportedAt',
          'category',
          'observedAt',
          'notice'
        ].every((field) => {
          const value = source[field as keyof typeof source]
          return (
            value === undefined ||
            (typeof value === 'string' && value.length <= 1000)
          )
        }) &&
        safeDrmSourceUrl(source.url)
    ) &&
    combinedDrmStatus(report.sources) === report.status
  )
}
async function readConfirmed(key: string) {
  try {
    const text = await readFile(
      join(confirmedDirectory(), key + '.json'),
      'utf8'
    )
    if (text.length > 256 * 1024) return undefined
    const report = JSON.parse(text) as ReleaseDrmReport
    return validReport(key, report) && isConfirmedDrmReport(report)
      ? report
      : undefined
  } catch {
    return undefined
  }
}
async function saveConfirmed(key: string, report: ReleaseDrmReport) {
  const target = join(confirmedDirectory(), key + '.json')
  if (isConfirmedDrmReport(report)) {
    await mkdir(confirmedDirectory(), { recursive: true })
    await writeFile(target + '.tmp', JSON.stringify(report), 'utf8')
    await rename(target + '.tmp', target)
  } else {
    await unlink(target).catch((error: NodeJS.ErrnoException) => {
      if (error.code !== 'ENOENT') throw error
    })
  }
}
async function readCache() {
  try {
    const text = await readFile(file(), 'utf8')
    if (text.length > 2 * 1024 * 1024) return
    const data = JSON.parse(text)
    if (!Array.isArray(data) || data.length > 500) return
    for (const entry of data) {
      const report = entry?.report as ReleaseDrmReport
      if (validReport(entry?.key || '', report)) {
        reports.set(entry.key, report)
        // Migrate previous confirmed results before the rolling cache can evict them.
        if (isConfirmedDrmReport(report) && !(await readConfirmed(entry.key)))
          await saveConfirmed(entry.key, report).catch(() => undefined)
      }
    }
  } catch {
    /* Catalogue and saved follows remain usable if this optional cache fails. */
  }
}
async function persist(key: string, report: ReleaseDrmReport) {
  writer = writer
    .catch(() => undefined)
    .then(async () => {
      await mkdir(directory(), { recursive: true })
      await writeFile(
        join(directory(), 'drm-cache.tmp'),
        JSON.stringify(
          [...reports].slice(-500).map(([key, report]) => ({ key, report }))
        ),
        'utf8'
      )
      await rename(join(directory(), 'drm-cache.tmp'), file())
      // One file per confirmed game: confirmations survive the 500-entry rolling cache.
      await saveConfirmed(key, report)
    })
  await writer
}

async function readGame(url: string) {
  // Public metadata needs no login cookies or persistent site scripts. Our validated
  // report cache is kept separately, so an old service worker cannot poison reads.
  const partition = session.fromPartition('ghost-drm-metadata-v1')
  if (!sourceReady) {
    partition.setPermissionRequestHandler(
      (_webContents, _permission, callback) => callback(false)
    )
    partition.webRequest.onBeforeRequest((details, callback) => {
      const host = new URL(details.url).hostname
      callback({
        cancel:
          ![
            'isitcracked.com',
            'cdn.isitcracked.com',
            'lhvknkrfhehcclzlabsl.supabase.co',
            'bopxedkcjdpeiysqlsmn.supabase.co'
          ].includes(host) ||
          ['image', 'media', 'font'].includes(details.resourceType)
      })
    })
    sourceReady = true
  }
  const window = new BrowserWindow({
    show: false,
    webPreferences: {
      session: partition,
      sandbox: true,
      contextIsolation: true,
      nodeIntegration: false,
      webSecurity: true,
      backgroundThrottling: false
    }
  })
  window.webContents.setAudioMuted(true)
  window.webContents.setWindowOpenHandler(() => ({ action: 'deny' }))
  const guard = (event: Electron.Event, target: string) => {
    if (new URL(target).origin !== 'https://isitcracked.com')
      event.preventDefault()
  }
  window.webContents.on('will-navigate', guard)
  window.webContents.on('will-redirect', guard)
  const deadline = setTimeout(() => {
    if (!window.isDestroyed()) window.destroy()
  }, 25000)
  try {
    await window.loadURL(url)
    for (let attempt = 0; attempt < 60; attempt++) {
      const data = await window.webContents.executeJavaScript(`(() => {
        const heading = document.querySelector('h1');
        if (/game not found|couldn't find this game|game does not exist/i.test(document.body?.innerText || '')) return {title:'Game not found'};
        if (!heading) return undefined;
        const info = heading.parentElement?.parentElement;
        const allowed = /^(cracked|uncracked|unreleased|hypervisor|bypassed|drm free|drm removed|early access)$/i;
        const status = Array.from(info?.querySelectorAll('span') || []).map(e => e.textContent.trim()).find(text => allowed.test(text));
        const field = name => {
          const label = Array.from(document.querySelectorAll('span')).find(e=>e.textContent.trim().toLowerCase()===name.toLowerCase());
          return label?.parentElement?.parentElement?.querySelector('p')?.textContent?.trim();
        };
        return {title:heading.textContent.trim(),status,protection:field('DRM Protection'),crackDate:field('Crack Date'),group:field('Scene Group')};
      })()`)
      if (data?.status || (data?.title && /not found/i.test(data.title)))
        return data
      await new Promise((resolve) => setTimeout(resolve, 300))
    }
    throw new Error('IsItCracked não forneceu um status legível.')
  } finally {
    clearTimeout(deadline)
    if (!window.isDestroyed()) window.destroy()
  }
}

async function readMatchingGame(title: string) {
  for (const alias of drmTitleAliases(title)) {
    const url = 'https://isitcracked.com/game/' + drmGameSlug(alias)
    const value = await readGame(url)
    if (normalizeDrmTitle(value?.title || '') === normalizeDrmTitle(title)) {
      const source = parseIsItCracked(value, title, url)
      if (source) return source
    }
  }
  return undefined
}

async function redditJson(url: string) {
  if (Date.now() < redditUnavailableUntil)
    throw new Error(
      'Reddit · CrackWatch indisponível nesta conexão; consulte o link da fonte.'
    )
  const response = await net.fetch(url, {
    signal: AbortSignal.timeout(12000),
    redirect: 'error',
    credentials: 'omit',
    headers: { 'User-Agent': 'Ghost-Launcher/0.3 (public DRM metadata)' }
  })
  if (!response.ok) {
    if ([401, 403, 429].includes(response.status))
      redditUnavailableUntil = Date.now() + 60 * 60 * 1000
    throw new Error(
      `Reddit · CrackWatch não permitiu a consulta (HTTP ${response.status}).`
    )
  }
  const text = await response.text()
  if (text.length > 2 * 1024 * 1024)
    throw new Error('Resposta do CrackWatch muito grande.')
  return JSON.parse(text)
}

async function readIndex(title: string, refresh = false) {
  if (!indexRead && (refresh || Date.now() - indexCheckedAt >= 15 * 60000)) {
    indexRead = redditJson(
      CRACKWATCH_INDEX.replace(/\/$/, '.json?raw_json=1&limit=1')
    )
    try {
      indexValue = await indexRead
      indexCheckedAt = Date.now()
    } finally {
      indexRead = undefined
    }
  } else if (indexRead) await indexRead
  return parseCrackWatchIndex(indexValue, title)
}

async function readReddit(title: string) {
  const url = new URL('https://www.reddit.com/r/CrackWatch/search.json')
  url.searchParams.set(
    'q',
    drmTitleAliases(title)
      .map((alias) => '"' + alias + '"')
      .join(' OR ')
  )
  url.searchParams.set('restrict_sr', 'on')
  url.searchParams.set('sort', 'new')
  url.searchParams.set('limit', '25')
  url.searchParams.set('type', 'link')
  return parseCrackWatch(await redditJson(url.href), title)
}

export async function getReleaseDrm(query: {
  id: string
  title: string
  refresh?: boolean
  priority?: boolean
}): Promise<ReleaseDrmReport> {
  if (
    !query ||
    typeof query.id !== 'string' ||
    !/^[a-z0-9._~-]{1,200}$/i.test(query.id) ||
    typeof query.title !== 'string' ||
    !query.title.trim() ||
    query.title.length > 300 ||
    (query.refresh !== undefined && typeof query.refresh !== 'boolean') ||
    (query.priority !== undefined && typeof query.priority !== 'boolean') ||
    [...query.title].some((character) => character.charCodeAt(0) < 32)
  )
    throw new Error('Jogo inválido para consulta de DRM.')
  loading ||= readCache()
  await loading
  const key = reportKey(query)
  const saved = (await readConfirmed(key)) || reports.get(key)
  if (
    saved &&
    !query.refresh &&
    (isConfirmedDrmReport(saved) ||
      (saved.lookupVersion === lookupVersion &&
        Date.now() - Date.parse(saved.checkedAt) < 15 * 60000))
  )
    return saved
  return queue.run(
    key,
    async () => {
      const search = new URL('https://www.reddit.com/r/CrackWatch/search/')
      search.searchParams.set('q', query.title)
      search.searchParams.set('restrict_sr', 'on')
      search.searchParams.set('sort', 'new')
      const results = await Promise.allSettled([
        readMatchingGame(query.title),
        readReddit(query.title),
        getCrackWatchSheetSources(query.title, query.refresh),
        readIndex(query.title, query.refresh),
        getAdditionalDrmSources(query.title, query.refresh)
      ])
      const primary =
        results[0].status === 'fulfilled' ? results[0].value : undefined
      const community =
        results[1].status === 'fulfilled' ? results[1].value : []
      const sheet =
        results[2].status === 'fulfilled' ? results[2].value : undefined
      const index = results[3].status === 'fulfilled' ? results[3].value : []
      const additional =
        results[4].status === 'fulfilled' ? results[4].value : []
      const sources = [
        primary || {
          name: 'IsItCracked' as const,
          url: 'https://isitcracked.com/games'
        },
        ...community,
        ...(!community.length
          ? [{ name: 'CrackWatch' as const, url: search.href }]
          : []),
        ...(sheet?.sources.length
          ? sheet.sources
          : [
              {
                name: 'CrackWatchSheet' as const,
                url: drmSheetUrl('737179558')
              }
            ]),
        ...(index.length
          ? index
          : [{ name: 'CrackWatchIndex' as const, url: CRACKWATCH_INDEX }]),
        ...additional
      ]
      const warning = [
        ...results
          .filter((result) => result.status === 'rejected')
          .map((result) => {
            const reason: unknown = result.reason
            return reason instanceof Error
              ? reason.message
              : 'Fonte indisponível.'
          }),
        ...(sheet?.warning ? [sheet.warning] : []),
        ...additional
          .filter(
            (source) =>
              source.name !== 'HizSearch' &&
              source.notice &&
              /indisponível|manutenção|verificação|não forneceu/i.test(
                source.notice
              )
          )
          .map(
            (source) =>
              `${releaseDrmSourceLabels[source.name]}: ${source.notice}`
          ),
        ...(!primary
          ? ['IsItCracked: título ou status não confirmado para este jogo.']
          : [])
      ]
        .filter((value, index, values) => values.indexOf(value) === index)
        .join(' ')
      let report: ReleaseDrmReport = {
        id: query.id,
        title: query.title,
        platform: 'PC',
        checkedAt: new Date().toISOString(),
        status: combinedDrmStatus(sources),
        sources,
        lookupVersion,
        ...(sheet?.stale ? { stale: true } : {}),
        ...(warning ? { warning } : {})
      }
      // A blocked or changed page cannot replace previously confirmed source evidence.
      if (saved && warning) {
        const preserved = saved.sources.filter(
          (source) =>
            (source.status || source.protection) &&
            !sources.some(
              (current) =>
                current.name === source.name &&
                (current.status || current.protection)
            )
        )
        if (preserved.length) {
          report = {
            ...report,
            sources: [
              ...sources.filter(
                (source) => !preserved.some((old) => old.name === source.name)
              ),
              ...preserved
            ].slice(0, 24),
            stale: true,
            checkedAt: saved.checkedAt
          }
          report.status = combinedDrmStatus(report.sources)
        }
      }
      reports.delete(key)
      reports.set(key, report)
      if (reports.size > 500) reports.delete(reports.keys().next().value!)
      try {
        await persist(key, report)
      } catch {
        report.warning = [report.warning, 'Falha ao guardar a consulta de DRM.']
          .filter(Boolean)
          .join(' ')
      }
      return report
    },
    query.priority
  )
}

