        {
          key: 'results',
          month: undefined,
          groups: [{ key: 'results', date: undefined, label: '', products }]
        }
      ]
    return releaseCalendarSections(products, view !== 'tracking')
  }, [products, view, term])
  const calendarContext = [categoryName(prefs.category), ...platformNames].join(
    ' / '
  )
  const loadMore = useCallback(
    async (direction: 'forward' | 'backward' = 'forward') => {
      const cursor =
        direction === 'forward' ? catalog?.nextCursor : catalog?.previousCursor
      if (
        !catalog ||
        !cursor ||
        (direction === 'forward' && !catalog.hasMore) ||
        busy ||
        selectedId ||
        view === 'tracking'
      )
        return
      const current = generation.current
      if (pageRequest.current?.generation === current) return
      if (loadedCursors.current.has(cursor)) {
        setError(
          'A fonte repetiu uma página. Os títulos carregados foram preservados.'
        )
        return
      }
      pageRequest.current = { generation: current, cursor }
      setBusy(true)
      setError('')
      try {
        const result = await window.api.releasesCatalog({
          category: prefs.category,
          platforms: JSON.parse(platformsKey),
          region: prefs.region,
          cursor,
          view: view === 'hot' ? 'hot' : 'calendar',
          interval,
          date,
          search: term,
          tag: appliedTag,
          refresh: reload > 0
        })
        if (current !== generation.current) return
        const next = appendReleasePage(catalog, result, cursor, direction)
        const followingCursor =
          direction === 'forward' ? next.nextCursor : next.previousCursor
        if (followingCursor && loadedCursors.current.has(followingCursor))
          throw new Error(
            'A fonte repetiu uma página. Os títulos carregados foram preservados.'
          )
        loadedCursors.current.add(cursor)
        if (direction === 'backward' && resultsPanel.current) {
          const panel = resultsPanel.current
          const top = panel.getBoundingClientRect().top
          const element = [...panel.querySelectorAll('.nr-card')].find(
            (card) => card.getBoundingClientRect().bottom > top
          )
          if (element)
            scrollAnchor.current = {
              element,
              top: element.getBoundingClientRect().top,
              generation: current
            }
        }
        setCatalog(next)
      } catch (error) {
        if (current === generation.current) setError(String(error))
      } finally {
        if (current === generation.current) {
          pageRequest.current = null
          setBusy(false)
        }
      }
    },
    [
      catalog,
      busy,
      selectedId,
      view,
      prefs.category,
      prefs.region,
      platformsKey,
      interval,
      date,
      term,
      appliedTag,
      reload
    ]
  )

  useEffect(() => {
    if (
      !catalog ||
      catalog.stale ||
      busy ||
      error ||
      selectedId ||
      view === 'tracking' ||
      !resultsPanel.current
    )
      return
    const observer = new IntersectionObserver(
      (entries) => {
        const previous = entries.find(
          (entry) =>
            entry.target === previousPageSentinel.current &&
            entry.isIntersecting
        )
        if (previous) void loadMore('backward')
        else if (
          entries.some(
            (entry) =>
              entry.target === nextPageSentinel.current && entry.isIntersecting
          )
        )
          void loadMore('forward')
      },
      { root: resultsPanel.current, rootMargin: '250px 0px 600px' }
    )
    if (
      catalog.previousCursor &&
      view === 'calendar' &&
      !term &&
      previousPageSentinel.current
    )
      observer.observe(previousPageSentinel.current)
    if (catalog.hasMore && nextPageSentinel.current)
      observer.observe(nextPageSentinel.current)
    return () => observer.disconnect()
  }, [catalog, busy, error, selectedId, view, term, loadMore])

  useLayoutEffect(() => {
    const anchor = scrollAnchor.current
    if (
      anchor &&
      anchor.generation === generation.current &&
      anchor.element.isConnected &&
      resultsPanel.current
    )
      resultsPanel.current.scrollTop +=
        anchor.element.getBoundingClientRect().top - anchor.top
    scrollAnchor.current = null
    const panel = resultsPanel.current
    const initial = initialCalendarAnchor.current
    if (initial && panel) {
      const times = [
        ...panel.querySelectorAll<HTMLTimeElement>(
          '.nr-day-heading time[datetime]'
        )
      ]
      const target =
        times.find((time) => time.dateTime >= initial) || times.at(-1)
      if (target) {
        const month = target.closest('.nr-month')
        const first = month?.querySelector('.nr-day-heading time[datetime]')
        const destination =
          first === target ? month! : target.closest('.nr-day-heading')!
        panel.scrollTop +=
          destination.getBoundingClientRect().top -
          panel.getBoundingClientRect().top -
          16
      }
      initialCalendarAnchor.current = null
    }
  }, [catalog])

  useEffect(() => {
    const panel = resultsPanel.current
    if (!panel || view !== 'calendar' || term) return
    const headings = [...panel.querySelectorAll<HTMLElement>('.nr-day-heading')]
    let frame = 0
    const updateDay = () => {
      frame = 0
      const top = panel.getBoundingClientRect().top + 20
      const current =
        headings.find(
          (heading) =>
            (heading.closest('.nr-group')?.getBoundingClientRect().bottom ||
              0) > top
        ) || headings.at(-1)
      if (!current) return
      const next = {
        date: current.dataset.date || undefined,
        label: current.dataset.label || ''
      }
      setVisibleDay((previous) =>
        previous.date === next.date && previous.label === next.label
          ? previous
          : next
      )
    }
    const onScroll = () => {
      if (!frame) frame = requestAnimationFrame(updateDay)
    }
    updateDay()
    panel.addEventListener('scroll', onScroll, { passive: true })
    return () => {
      panel.removeEventListener('scroll', onScroll)
      cancelAnimationFrame(frame)
    }
  }, [catalog, view, term, prefs.layout])

  return (
    <main
      className={`NativeReleases NativeReleases--${prefs.theme}${calendarExpanded ? ' NativeReleases--expanded' : ''}`}
    >
      <ReleaseNavigation
        categories={categories}
        category={prefs.category}
        platforms={prefs.platforms}
        region={prefs.region}
        theme={prefs.theme}
        tag={tag}
        tracked={tracked}
        tracking={view === 'tracking'}
        onCategory={(category) => {
          changePrefs({ category, platforms: [] })
          setTag('')
        }}
        onPlatforms={(platforms) => changePrefs({ platforms })}
        onRegion={(region) => changePrefs({ region })}
        onTheme={() =>
          changePrefs({ theme: prefs.theme === 'dark' ? 'light' : 'dark' })
        }
        onTag={setTag}
        onSearch={() => searchInput.current?.focus()}
        onCalendar={() => {
          setView('calendar')
          setSearch('')
        }}
        onTracking={(category = 'all', platform = '') => {
          setView('tracking')
          changePrefs({ category, platforms: platform ? [platform] : [] })
          setSearch('')
          setTag('')
        }}
      />
      <section className="nr-workspace" aria-label="Catálogo de lançamentos">
        <header className="nr-header">
          <form
            className="nr-search"
            onSubmit={(event) => {
              event.preventDefault()
              setTerm(search.trim())
            }}
          >
            <Icon icon={faSearch} />
            <input
              ref={searchInput}
              aria-label="Buscar lançamentos"
              value={search}
              onChange={(event) => setSearch(event.target.value)}
              placeholder="Buscar jogos, filmes, séries e muito mais…"
            />
            {search && (
              <button
                type="button"
                aria-label="Limpar busca"
                onClick={() => setSearch('')}
              >
                <Icon icon={faXmark} />
              </button>
            )}
          </form>
          <button
            title="Atualizar lançamentos"
            aria-label="Atualizar lançamentos"
            disabled={busy}
            onClick={() => {
              setReload((value) => value + 1)
              void checkTodayReleases()
            }}
          >
            <Icon icon={faRotate} spin={busy} />
          </button>
        </header>
        <ReleaseToolbar
          view={view}
          layout={prefs.layout}
          interval={interval}
          anchorDate={date}
          visibleDay={visibleDay}
          context={calendarContext}
          searching={!!term}
          expanded={calendarExpanded}
          onView={setView}
          onLayout={(layout) => changePrefs({ layout })}
          onInterval={setInterval}
          onDate={(value) => {
            setReload((previous) => previous + 1)
            setDate(value)
          }}
          onToday={goToToday}
          onExpand={() => setCalendarExpanded(!calendarExpanded)}
          drmCheck={{
            count: drmGames.length,
            busy: drmBusy,
            completed: drmProgress?.completed || 0,
            total: drmProgress?.total || 0,
            onClick: () => void checkAllDrm()
          }}
        />
        {drmMessage && (
          <div className="nr-notice" role="status">
            {drmMessage}
            <button
              aria-label="Fechar resultado da verificação de DRM"
              onClick={() => setDrmMessage('')}
            >
              <Icon icon={faXmark} />
            </button>
          </div>
        )}
        {view === 'tracking' && (
          <div className="nr-backup-bar">
            <span>
              <Icon icon={faCloud} />{' '}
              {cloud
                ? 'Incluídos no próximo backup da sua conta de nuvem.'
                : 'Salvos neste dispositivo. Conecte uma nuvem para fazer backup.'}
            </span>
            <button onClick={() => navigate('/settings/general')}>
              Configurar backup
            </button>
            <button
              onClick={() => {
                try {
                  exportCalendar(visibleTracked)
                } catch (error) {
                  setSyncMessage(String(error))
                }
              }}
            >
              <Icon icon={faDownload} /> Calendário .ics
            </button>
          </div>
        )}
        {syncMessage && (
          <div className="nr-notice" role="status">
            {syncMessage}
            <button
              aria-label="Fechar aviso"
              onClick={() => setSyncMessage('')}
            >
              <Icon icon={faXmark} />
            </button>
          </div>
        )}
        {catalog?.warning && (
          <p className="nr-notice" role="status">
            {catalog.warning}
          </p>
        )}
        {error && (
          <div className="nr-error" role="alert">
            <strong>Não foi possível consultar a fonte</strong>
            <p>{error}</p>
            <button onClick={() => setReload((value) => value + 1)}>
              Tentar novamente
            </button>
            <button onClick={() => setView('tracking')}>
              Ver monitorados salvos
            </button>
          </div>
        )}
        <div className="nr-results" aria-busy={busy} ref={resultsPanel}>
          {catalog?.previousCursor && view === 'calendar' && !term && (
            <div
              ref={previousPageSentinel}
              className="nr-pagination nr-pagination--previous"
              aria-live="polite"
            >
              <button
                className="nr-load-more"
                disabled={busy}
                onClick={() => void loadMore('backward')}
              >
                {busy ? 'Carregando…' : 'Ver lançamentos anteriores'}
              </button>
            </div>
          )}
          {busy && !products.length && (
            <div className="nr-empty" role="status">
              <Icon icon={faRotate} spin />
              <h2>Consultando lançamentos…</h2>
              <p>Carregando as datas da fonte.</p>
            </div>
          )}
          {!busy && !error && !products.length && (
            <div className="nr-empty">
              <Icon icon={view === 'tracking' ? faBell : faCalendarDays} />
              <h2>
                {view === 'tracking'
                  ? 'Nenhum título acompanhado neste filtro'
                  : 'Nenhum lançamento encontrado'}
              </h2>
              <p>
                {view === 'tracking'
                  ? 'Use o sino de um título para acompanhar suas datas e receber avisos.'
                  : 'Tente outra data, categoria ou busca.'}
              </p>
            </div>
          )}
          {sections.map((section) => (
            <section
              className={section.month ? 'nr-month' : 'nr-period'}
              key={section.key}
            >
              {section.month && (
                <h2 className="nr-month-title">
                  {new Date(`${section.month}-01T12:00:00`).toLocaleDateString(
                    'pt-BR',
                    { month: 'long' }
                  )}
                  {section.month.slice(0, 4) !==
                    localReleaseDay().slice(0, 4) &&
                    ` ${section.month.slice(0, 4)}`}
                </h2>
              )}
              <div className="nr-month-days">
                {section.groups.map(
                  ({
                    key,
                    date: day,
                    label: sourceLabel,
                    products: entries
                  }) => {
                    const label = day ? dateText(day) : sourceLabel
                    const past = !!day && day < localReleaseDay()
                    return (
                      <section className="nr-group" key={key}>
                        {label && (
                          <h3
                            className={`nr-day-heading${past ? ' is-past' : ''}`}
                            data-date={day}
                            data-label={label}
                          >
                            <Icon
                              icon={past ? faCircleCheck : faCalendarDays}
                            />
                            <time dateTime={day} title={label}>
                              {shortDateText(day, label)}
                            </time>
                            <span className="nr-relative-date">
                              {relativeReleaseDate(day)}
                            </span>
                            <span className="nr-group-line" />
                            <span
                              className="nr-group-category"
                              title={calendarContext}
                            >
                              {calendarContext}
                            </span>
                            {day && view === 'calendar' && (
                              <button
                                className="nr-day-expand"
                                title={`Ver lançamentos de ${label}`}
                                aria-label={`Ver lançamentos de ${label}`}
                                onClick={() => {
                                  if (day === date)
                                    setReload((value) => value + 1)
                                  else setDate(day)
                                }}
                              >
                                <Icon icon={faExpand} />
                              </button>
                            )}
                          </h3>
                        )}
                        <div
                          className={`nr-products nr-products--${prefs.layout}`}
                        >
                          {entries.map((product) => {
                            const followed = isReleaseTracked(
                              product.id,
                              null,
                              prefs.region
                            )
                            return (
                              <article
                                className={`nr-card ${product.heroImage && prefs.layout === 'cards' ? 'nr-card--featured' : ''}`}
                                key={product.id}
                                style={
                                  product.heroImage && prefs.layout === 'cards'
                                    ? {
                                        backgroundImage: `linear-gradient(0deg,rgba(123,97,255,.18),rgba(123,97,255,.18)),linear-gradient(90deg,rgba(13,11,34,.78) 10%,rgba(13,11,34,.12) 100%),url("${product.heroImage}")`
                                      }
                                    : undefined
                                }
                              >
                                <button
                                  className="nr-card-open"
                                  onClick={() => setSelected(product)}
                                  aria-label={`Detalhes de ${product.title}`}
                                >
                                  <div className="nr-cover">
                                    {product.heroImage && (
                                      <span className="nr-feature-label">
                                        <Icon icon={faFire} /> Em destaque
                                      </span>
                                    )}
                                    {product.image ? (
                                      <img
                                        src={product.image}
                                        alt=""
                                        loading="lazy"
                                        onError={(event) => {
                                          event.currentTarget.style.visibility =
                                            'hidden'
                                        }}
                                      />
                                    ) : (
                                      <Icon
                                        icon={categoryIcon(product.category)}
                                      />
                                    )}
                                  </div>
                                  <div className="nr-card-copy">
                                    <span className="nr-type">
                                      {categoryName(product.category)}
                                    </span>
                                    <h4 title={product.title}>
                                      {product.title}
                                    </h4>
                                    <p title={product.platforms.join(' / ')}>
                                      <Icon
                                        icon={categoryIcon(product.category)}
                                      />{' '}
                                      {product.platforms
                                        .slice(0, 3)
                                        .join(' / ') ||
                                        'Plataforma a confirmar'}
                                      {product.platforms.length > 3 &&
                                        ` +${product.platforms.length - 3}`}
                                    </p>
                                    {view === 'tracking' &&
                                      visibleTracked.some(
                                        (entry) =>
                                          entry.product.id === product.id &&
                                          entry.updateWarning
                                      ) && (
                                        <small className="nr-card-warning">
                                          Dados preservados · confira o aviso
                                          nos detalhes
                                        </small>
                                      )}
                                    {(view === 'hot' || term) && (
                                      <small className="nr-card-release">
                                        {dateText(
                                          product.releaseDate,
                                          product.dateLabel
                                        )}
                                      </small>
                                    )}
                                  </div>
                                </button>
                                <div className="nr-card-actions">
                                  {['games', 'movies', 'tv-series'].includes(
                                    product.category
                                  ) && (
                                    <button
                                      className="nr-card-play"
                                      title={`Ver trailers de ${product.title}`}
                                      aria-label={`Ver trailers de ${product.title}`}
                                      onClick={() => {
                                        playRequested.current = product.id
                                        setSelected(product)
                                      }}
                                    >
                                      <Icon icon={faPlay} />
                                    </button>
                                  )}
                                  <button
                                    className={followed ? 'is-followed' : ''}
                                    aria-pressed={followed}
                                    aria-label={`${followed ? 'Deixar de monitorar' : 'Monitorar'} ${product.title}`}
                                    onClick={() => monitor(product)}
                                  >
                                    <Icon icon={followed ? faCheck : faBell} />
                                    <span>
                                      {product.popularity ||
                                        (followed ? 'Salvo' : 'Seguir')}
                                    </span>
                                  </button>
                                  {product.category === 'games' && (
                                    <ReleaseDrmBadge
                                      product={product}
                                      onOpen={() => setSelected(product)}
                                    />
                                  )}
                                  {(view === 'hot' || term) && (
                                    <span
                                      className="nr-card-date"
                                      title={dateText(
                                        product.releaseDate,
                                        product.dateLabel
                                      )}
                                    >
                                      <Icon icon={faCalendarDays} />{' '}
                                      {shortDateText(
                                        product.releaseDate,
                                        product.dateLabel
                                      )}
                                    </span>
                                  )}
                                </div>
                                {view === 'tracking' &&
                                  visibleTracked
                                    .filter(
                                      (entry) => entry.product.id === product.id
                                    )
                                    .map((entry) => (
                                      <div
                                        className="nr-follow-row"
                                        key={entry.id}
                                      >
                                        <span>
                                          {entry.platform ||
                                            'Todas as plataformas'}
                                        </span>
                                        <label>
                                          <input
                                            type="checkbox"
                                            checked={entry.notify}
                                            onChange={(event) =>
                                              setTrackedReleaseNotifications(
                                                entry.id,
                                                event.target.checked
                                              )
                                            }
                                          />{' '}
                                          Avisar
                                        </label>
                                        <button
                                          aria-label={`Remover monitoramento de ${product.title} ${entry.platform || 'todas as plataformas'}`}
                                          onClick={() =>
                                            removeTrackedRelease(entry.id)
                                          }
                                        >
                                          <Icon icon={faXmark} />
                                        </button>
                                      </div>
                                    ))}
                              </article>
                            )
                          })}
                        </div>
                      </section>
                    )
                  }
                )}
              </div>
            </section>
          ))}
          {catalog?.hasMore && view !== 'tracking' && (
            <div
              ref={nextPageSentinel}
              className="nr-pagination"
              aria-live="polite"
            >
              <button
                className="nr-load-more"
                disabled={busy}
                onClick={() => void loadMore()}
              >
                {busy ? 'Carregando…' : 'Carregar próximos lançamentos'}
              </button>
            </div>
          )}
        </div>
        <footer className="nr-footer">
          <span>
            {products.length} títulos carregados
            {selectedCategory ? ` · ${selectedCategory.label}` : ''}
          </span>
          <span>
            Datas da região {prefs.region === 'us' ? 'EUA' : 'Reino Unido'} ·
            Estimativas podem mudar
          </span>
        </footer>
      </section>
      <dialog
        className={`nr-detail ${detailExpanded ? 'nr-detail--expanded' : ''}`}
        ref={dialog}
        onCancel={() => setSelected(null)}
        onClose={() => setSelected(null)}
        onClick={(event) => {
          if (event.target === event.currentTarget) setSelected(null)
        }}
        aria-labelledby="nr-detail-title"
      >
        {selected && (
          <ReleaseDetails
            key={`${selected.id}:${prefs.region}`}
            product={selected}
            region={prefs.region}
            busy={detailBusy}
            error={detailError}
            follow={selectedFollow}
            video={video}
            expanded={detailExpanded}
            isTracked={isReleaseTracked}
            onMonitor={monitor}
            onClose={() => setSelected(null)}
            onExpand={() => setDetailExpanded(!detailExpanded)}
            onRegion={(region) => changePrefs({ region })}
            onVideo={setVideo}
            onTag={(tag) => {
              setTag(tag)
              setSearch('')
              changePrefs({ category: selected.category, platforms: [] })
              setView('calendar')
              setSelected(null)
            }}
            onResume={() => {
              resumeTrackedReleaseUpdates(selected.id, prefs.region)
              void checkTodayReleases(true)
            }}
            onRestore={(at) => {
              if (!selectedFollow) return
              try {
                setSelected(restoreTrackedReleaseVersion(selectedFollow.id, at))
                setSyncMessage('Versão recuperada neste dispositivo.')
              } catch (error) {
                setDetailError(String(error))
              }
            }}
          />
        )}
      </dialog>
    </main>
  )
}

import { useEffect, useRef, useState } from 'react'
import { FontAwesomeIcon as Icon } from '@fortawesome/react-fontawesome'
import {
  faClock,
  faLock,
  faQuestion,
  faRotate,
  faTriangleExclamation,
  faUnlock
} from '@fortawesome/free-solid-svg-icons'
import type { ReleaseProduct } from 'common/types/releases'
import type { ReleaseDrmReport, ReleaseDrmStatus } from 'common/releaseDrm'
import {
  releaseDrmLabels,
  releaseDrmSourceLabels,
  safeDrmSourceUrl,
  isConfirmedDrmReport
} from 'common/releaseDrm'
import {
  requestReleaseDrm as request,
  subscribeReleaseDrm,
  hasSavedDrmConfirmation
} from 'frontend/helpers/releaseDrmRequests'
import './drm.css'

const dateLabel = (date: string) =>
  /^\d{4}-\d{2}-\d{2}$/.test(date)
    ? new Date(date + 'T12:00:00Z').toLocaleDateString('pt-BR')
    : date
const statusIcon = (status: ReleaseDrmStatus) =>
  status === 'cracked' || status === 'drm-free'
    ? faUnlock
    : status === 'uncracked'
      ? faLock
      : status === 'unreleased' || status === 'early-access'
        ? faClock
        : status === 'bypassed' || status === 'conflicting'
          ? faTriangleExclamation
          : faQuestion

export function ReleaseDrmBadge({
  product,
  onOpen
}: {
  product: ReleaseProduct
  onOpen: () => void
}) {
  const ref = useRef<HTMLButtonElement>(null)
  const [report, setReport] = useState<ReleaseDrmReport | null>(null)
  const [busy, setBusy] = useState(false)
  useEffect(() => {
    const element = ref.current
    if (!element) return
    let alive = true
    const update = (report: ReleaseDrmReport) => {
      if (alive) setReport(report)
    }
    const unsubscribe = subscribeReleaseDrm(product, update)
    let visible = false
    const load = () => {
      setBusy(true)
      void request({ id: product.id, title: product.title })
        .then((report) => {
          if (alive) setReport(report)
        })
        .catch(() => undefined)
        .finally(() => {
          if (alive) setBusy(false)
        })
    }
    const observer = new IntersectionObserver(
      (entries) => {
        visible = entries.some((entry) => entry.isIntersecting)
        if (visible) load()
      },
      { root: element.closest('.nr-results'), rootMargin: '80px' }
    )
    observer.observe(element)
    const periodic = setInterval(() => {
      if (visible && !document.hidden && !hasSavedDrmConfirmation(product))
        load()
    }, 15 * 60000)
    return () => {
      alive = false
      observer.disconnect()
      clearInterval(periodic)
      unsubscribe()
    }
  }, [product.id, product.title])
  const status = report?.status || 'unknown'
  const label = `DRM da versão PC: ${busy ? 'Consultando fontes' : releaseDrmLabels[status]}${report?.stale ? ' · consulta anterior' : ''}`
  return (
    <button
      ref={ref}
      className={`nr-drm-badge nr-drm--${status}`}
      aria-label={`${label} · ${product.title}`}
      title={label}
      onClick={onOpen}
    >
      <span>DRM</span>
      <Icon icon={busy ? faRotate : statusIcon(status)} spin={busy} />
    </button>
  )
}

export function ReleaseDrmDetails({ product }: { product: ReleaseProduct }) {
  const [report, setReport] = useState<ReleaseDrmReport | null>(null)
  const [busy, setBusy] = useState(false)
  const [error, setError] = useState('')
  const [revision, setRevision] = useState(0)
  useEffect(() => {
    let alive = true
    const unsubscribe = subscribeReleaseDrm(product, (report) => {
      if (alive) setReport(report)
    })
    setBusy(true)
    setError('')
    void request({ id: product.id, title: product.title }, revision > 0, true)
      .then((report) => {
        if (alive) setReport(report)
      })
      .catch(() => {
        if (alive) setError('Não foi possível consultar as fontes agora.')
      })
      .finally(() => {
        if (alive) setBusy(false)
      })
    return () => {
      alive = false
      unsubscribe()
    }
  }, [product.id, product.title, revision])
  const status = report?.status || 'unknown'
  const primary = report?.sources.find(
    (source) => source.protection || source.crackDate || source.group
  )
  const open = (url: string) => {
    const safe = safeDrmSourceUrl(url)
    if (safe) void window.api.openExternalUrl(safe)
  }
  return (
    <section className="nr-drm-details" aria-label="Status do DRM da versão PC">
      <div className="nr-drm-heading">
        <h3>DRM · versão PC</h3>
        <button
          aria-label="Atualizar status do DRM"
          disabled={busy}
          onClick={() => setRevision((value) => value + 1)}
        >
          <Icon icon={faRotate} spin={busy} />
        </button>
      </div>
      <p className={`nr-drm-summary nr-drm--${status}`}>
        <Icon icon={statusIcon(status)} />{' '}
        {busy && !report
          ? 'Consultando fontes de DRM…'
          : releaseDrmLabels[status]}
      </p>
      {primary &&
        (primary.protection || primary.crackDate || primary.group) && (
          <dl>
            {primary.protection && (
              <>
                <dt>Proteção informada</dt>
                <dd>{primary.protection}</dd>
              </>
            )}
            {primary.crackDate && (
              <>
                <dt>Data da quebra</dt>
                <dd>{dateLabel(primary.crackDate)}</dd>
              </>
            )}
            {primary.group && (
              <>
                <dt>Grupo informado</dt>
                <dd>{primary.group}</dd>
              </>
            )}
          </dl>
        )}
      {report?.sources.map((source, index) => (
        <div className="nr-drm-source" key={source.url + index}>
          <button onClick={() => open(source.url)}>
            {releaseDrmSourceLabels[source.name]}
          </button>
          <span>
            {source.status
              ? releaseDrmLabels[source.status]
              : source.protection
                ? 'Proteção listada'
                : source.availability === 'listed'
                  ? 'Jogo listado na fonte'
                  : 'Sem confirmação nesta consulta'}
          </span>
          {source.title && <small>{source.title}</small>}
          {source.category && <small>{source.category}</small>}
          {source.notice && <small>{source.notice}</small>}
          {source.protection && <small>{source.protection}</small>}
          {(source.crackDate || source.group) && (
            <small>
              {[
                source.crackDate ? dateLabel(source.crackDate) : undefined,
                source.group
              ]
                .filter(Boolean)
                .join(' · ')}
            </small>
          )}
          {source.observedAt && (
            <small>
              Base consultada em{' '}
              {new Date(source.observedAt).toLocaleString('pt-BR')}
            </small>
          )}
          {source.reportedAt && (
            <small>
              {new Date(source.reportedAt).toLocaleDateString('pt-BR')}
            </small>
          )}
        </div>
      ))}
      {report && (
        <small className="nr-drm-checked">
          {report.stale ? 'Consulta anterior preservada' : 'Consultado em'} ·{' '}
          {new Date(report.checkedAt).toLocaleString('pt-BR')}
        </small>
      )}
      {(error || report?.warning) && (
        <p className="nr-drm-warning">{error || report?.warning}</p>
      )}
      {report && isConfirmedDrmReport(report) && (
        <p className="nr-drm-note">
          Resultado salvo. Consultas automáticas encerradas para este jogo. Use
          Atualizar ou Verificar DRM para consultar novamente.
        </p>
      )}
      {status === 'unknown' && !busy && (
        <p className="nr-drm-note">
          Ausência de confirmação não significa que o jogo foi ou não foi
          quebrado.
        </p>
      )}
      {status === 'bypassed' && (
        <p className="nr-drm-note">
          Bypass relatado é exibido separadamente de uma quebra convencional do
          DRM.
        </p>
      )}
      <p className="nr-drm-note">
        Informações das fontes para PC. O status não se aplica às versões de
        console.
      </p>
    </section>
  )
}

import { useEffect, useRef } from 'react'
import { FontAwesomeIcon as Icon } from '@fortawesome/react-fontawesome'
import {
  faArrowDown,
  faBars,
  faBell,
  faCalendarDays,
  faChevronDown,
  faChevronLeft,
  faChevronRight,
  faCircleCheck,
  faCompress,
  faExpand,
  faFire,
  faRotate,
  faShieldHalved,
  faStop,
  faTableCellsLarge
} from '@fortawesome/free-solid-svg-icons'
import type { ReleaseQuery } from 'common/types/releases'
import { localReleaseDay } from 'frontend/helpers/releaseTracking'
import './toolbar.css'

export type ReleaseLayout = 'cards' | 'items' | 'rows'
export type ReleaseView = 'calendar' | 'hot' | 'tracking'
type Interval = NonNullable<ReleaseQuery['interval']>

export function shortCalendarDate(date?: string, fallback = 'A confirmar') {
  if (!date) return fallback
  return new Date(`${date}T12:00:00`)
    .toLocaleDateString('pt-BR', {
      day: 'numeric',
      month: 'short',
      ...(date.slice(0, 4) !== localReleaseDay().slice(0, 4)
        ? { year: 'numeric' }
        : {})
    })
    .replace(/ de /g, ' ')
}

export function relativeCalendarDate(date?: string) {
  if (!date) return ''
  const today = localReleaseDay()
  const days = Math.round((Date.parse(date) - Date.parse(today)) / 86400000)
  if (days === 0) return 'Hoje'
  if (days === 1) return 'Amanhã'
  if (days === -1) return 'Ontem'
  if (Math.abs(days) >= 90) {
    const months = Math.abs(
      (Number(date.slice(0, 4)) - Number(today.slice(0, 4))) * 12 +
        Number(date.slice(5, 7)) -
        Number(today.slice(5, 7))
    )
    return days > 0 ? `Em ${months} meses` : `Há ${months} meses`
  }
  return days > 0 ? `Em ${days} dias` : `Há ${-days} dias`
}

interface Props {
  view: ReleaseView
  layout: ReleaseLayout
  interval: Interval
  anchorDate: string
  visibleDay: { date?: string; label: string }
  context: string
  searching: boolean
  expanded: boolean
  onView: (view: ReleaseView) => void
  onLayout: (layout: ReleaseLayout) => void
  onInterval: (interval: Interval) => void
  onDate: (date: string) => void
  onToday: () => void
  onExpand: () => void
  drmCheck?: {
    count: number
    busy: boolean
    completed: number
    total: number
    onClick: () => void
  }
}

export default function ReleaseToolbar(props: Props) {
  const datePicker = useRef<HTMLDetailsElement>(null)
  const hotPicker = useRef<HTMLDetailsElement>(null)
  useEffect(() => {
    const closeOutside = (event: PointerEvent) => {
      for (const picker of [datePicker.current, hotPicker.current])
        if (picker?.open && !picker.contains(event.target as Node))
          picker.open = false
    }
    const closeWithEscape = (event: KeyboardEvent) => {
      if (event.key === 'Escape') {
        if (datePicker.current) datePicker.current.open = false
        if (hotPicker.current) hotPicker.current.open = false
      }
    }
    document.addEventListener('pointerdown', closeOutside)
    document.addEventListener('keydown', closeWithEscape)
    return () => {
      document.removeEventListener('pointerdown', closeOutside)
      document.removeEventListener('keydown', closeWithEscape)
    }
  }, [])
  const past =
    !!props.visibleDay.date && props.visibleDay.date < localReleaseDay()
  const changeMonth = (direction: number) => {
    const value = new Date(
      `${props.visibleDay.date || props.anchorDate}T12:00:00`
    )
    value.setDate(1)
    value.setMonth(value.getMonth() + direction)
    props.onDate(localReleaseDay(value))
    if (datePicker.current) datePicker.current.open = false
  }
  return (
    <div className="nr-toolbar">
      <div className="nr-toolbar-date">
        {props.view === 'calendar' && !props.searching && (
          <>
            <details className="nr-date-picker" ref={datePicker}>
              <summary
                className={past ? 'nr-current-day is-past' : 'nr-current-day'}
                aria-label="Escolher data do calendário"
              >
                <Icon icon={past ? faCircleCheck : faCalendarDays} />
                <span>
                  {shortCalendarDate(
                    props.visibleDay.date,
                    props.visibleDay.label
                  )}
                </span>
                <small>{relativeCalendarDate(props.visibleDay.date)}</small>
                <Icon icon={faChevronDown} />
              </summary>
              <div className="nr-toolbar-popup">
                <div className="nr-month-navigation">
                  <button
                    aria-label="Mês anterior"
                    onClick={() => changeMonth(-1)}
                  >
                    <Icon icon={faChevronLeft} />
                  </button>
                  <strong>Ir para uma data</strong>
                  <button
                    aria-label="Próximo mês"
                    onClick={() => changeMonth(1)}
                  >
                    <Icon icon={faChevronRight} />
                  </button>
                </div>
                <form
                  key={props.anchorDate}
                  onSubmit={(event) => {
                    event.preventDefault()
                    const value = String(
                      new FormData(event.currentTarget).get('date') || ''
                    )
                    if (value) props.onDate(value)
                    if (datePicker.current) datePicker.current.open = false
                  }}
                >
                  <label>
                    Dia, mês e ano
                    <input
                      type="date"
                      name="date"
                      aria-label="Data do calendário"
                      defaultValue={props.visibleDay.date || props.anchorDate}
                      required
                    />
                  </label>
                  <button type="submit" className="nr-primary">
                    Ver lançamentos
                  </button>
                </form>
                <button
                  className="nr-popup-today"
                  onClick={() => {
                    props.onToday()
                    if (datePicker.current) datePicker.current.open = false
                  }}
                >
                  Voltar para hoje
                </button>
              </div>
            </details>
            <button
              className="nr-today-button"
              title="Ir para hoje"
              aria-label="Ir para hoje"
              onClick={props.onToday}
            >
              <Icon icon={faArrowDown} />
              <span />
            </button>
          </>
        )}
      </div>
      <div className="nr-toolbar-modes">
        <div className="nr-tabs" aria-label="Visualização">
          <button
            aria-pressed={props.view === 'calendar'}
            onClick={() => props.onView('calendar')}
          >
            <Icon icon={faCalendarDays} /> Calendário
          </button>
          <div className="nr-hot-control">
            <button
              aria-pressed={props.view === 'hot'}
              onClick={() => props.onView('hot')}
            >
              <Icon icon={faFire} /> Populares
            </button>
            <details ref={hotPicker} className="nr-hot-picker">
              <summary aria-label="Período dos populares">
                <Icon icon={faChevronDown} />
              </summary>
              <div className="nr-toolbar-popup">
                {(
                  [
                    ['week', 'Esta semana'],
                    ['month', 'Este mês'],
                    ['year', 'Este ano'],
                    ['all', 'Todo o período']
                  ] as const
                ).map(([interval, label]) => (
                  <button
                    key={interval}
                    aria-pressed={props.interval === interval}
                    onClick={() => {
                      props.onInterval(interval)
                      props.onView('hot')
                      if (hotPicker.current) hotPicker.current.open = false
                    }}
                  >
                    {label}
                  </button>
                ))}
              </div>
            </details>
          </div>
          {props.view === 'tracking' && (
            <button aria-pressed="true">
              <Icon icon={faBell} /> Monitorados
            </button>
          )}
        </div>
        <div className="nr-layout" aria-label="Formato dos lançamentos">
          <button
            title="Capas"
            aria-label="Exibir cartões"
            aria-pressed={props.layout === 'cards'}
            onClick={() => props.onLayout('cards')}
          >
            <span className="nr-layout-cover" />
          </button>
          <button
            title="Cartões compactos"
            aria-label="Exibir cartões compactos"
            aria-pressed={props.layout === 'items'}
            onClick={() => props.onLayout('items')}
          >
            <Icon icon={faTableCellsLarge} />
          </button>
          <button
            title="Lista"
            aria-label="Exibir lista"
            aria-pressed={props.layout === 'rows'}
            onClick={() => props.onLayout('rows')}
          >
            <Icon icon={faBars} />
          </button>
        </div>
      </div>
      <div className="nr-toolbar-context">
        <h1 className="nr-context-title" title={props.context}>
          {props.view === 'tracking' ? 'Seus monitorados' : props.context}
        </h1>
        {props.drmCheck && (
          <button
            className="nr-drm-check"
            title={
              props.drmCheck.busy
                ? 'Parar a verificação após as consultas em andamento'
                : `Consultar novamente o DRM da versão PC de todos os ${props.drmCheck.count} jogos carregados e monitorados`
            }
            aria-label={
              props.drmCheck.busy
                ? 'Parar verificação de DRM'
                : 'Verificar DRM de todos os jogos carregados e monitorados'
            }
            disabled={!props.drmCheck.busy && !props.drmCheck.count}
            onClick={props.drmCheck.onClick}
          >
            <Icon
              icon={props.drmCheck.busy ? faRotate : faShieldHalved}
              spin={props.drmCheck.busy}
            />
            <span role="status" aria-live="polite">
              {props.drmCheck.busy
                ? `${props.drmCheck.completed}/${props.drmCheck.total}`
                : 'Verificar DRM'}
            </span>
            {props.drmCheck.busy && <Icon icon={faStop} />}
          </button>
        )}
        <button
          title={props.expanded ? 'Recolher calendário' : 'Expandir calendário'}
          aria-label={
            props.expanded ? 'Recolher calendário' : 'Expandir calendário'
          }
          onClick={props.onExpand}
        >
          <Icon icon={props.expanded ? faCompress : faExpand} />
        </button>
      </div>
    </div>
  )
}
